<script setup lang="ts">
import {computed,defineAsyncComponent,ref} from 'vue';
import type {Configuration,Tank,LiveReading,Metric} from './api';
import {displayMetric,unit,qualityNames,type Quantity} from './units';
import TankGraphic from './TankGraphic.vue';
import InstrumentControls from './InstrumentControls.vue';
const WirelessTasks=__AVERAGE_DELIVERY__?defineAsyncComponent(()=>import('./WirelessTasks.vue')):null;
const TrendBoard=defineAsyncComponent(()=>import('./TrendBoard.vue'));
const props=defineProps<{licensed:boolean;config:Configuration;tank:Tank;reading:LiveReading|undefined;valid:boolean;admin:boolean;canOperate:boolean;averageAllowed:boolean;dirty:boolean;alarmColor:string;alarmText:string}>();
const emit=defineEmits<{updated:[Configuration];edit:[Tank]}>();const showTrend=ref(false);
const shapes:Record<string,string>={Vertical:'立式罐',Sphere:'球罐',FloatingRoof:'浮顶罐'};
const value=(m:Metric|undefined,q:Quantity)=>props.valid?displayMetric(m,q,props.config.display):'—';
const points=computed(()=>props.reading?.atsPoints||[]),normalPoints=computed(()=>props.valid?points.value.filter(p=>p.temperatureC.quality==='Good').length:0);
const graphicPoints=computed(()=>props.tank.temperatureMode!=='Ats'?[]:Array.from({length:props.tank.atsPointCount},(_,n)=>{const point=points.value.find(p=>p.index===n+1);return {index:n+1,heightMm:props.tank.atsHeightsMm[n]??null,quality:props.valid?point?.temperatureC.quality||'Missing':'Missing',value:props.valid?point?.temperatureC.value??null:null}}));
function quality(m:Metric|undefined){return !props.valid?'无有效数据':m?.reason||qualityNames[m?.quality||'Missing']}
function date(t:string|null|undefined){return t?new Date(t).toLocaleString('zh-CN',{hour12:false}):'—'}
function pressure(index:number){const p=props.tank[index===1?'pressure1':'pressure2'],m=props.reading?.[index===1?'pressure1KPa':'pressure2KPa'];if(!props.valid||m?.quality!=='Good'||m.value===null)return '—';return (m.value/(p.unit==='MPa'?1000:p.unit==='Bar'?100:1)).toLocaleString('zh-CN',{minimumFractionDigits:3,maximumFractionDigits:3})}
</script>
<template><section class="detail-layout"><article class="panel detail-visual"><div class="tank-card-heading"><h2>{{tank.code}}</h2><button v-if="admin" class="text-button" @click="emit('edit',tank)">编辑配置</button></div><p v-if="tank.name" class="tank-display-name">{{tank.name}}</p><p class="help">{{tank.medium||'介质未填'}} · {{shapes[tank.shape]}} · {{tank.zone||'未分配罐区'}}</p><TankGraphic :shape="tank.shape" :height="tank.heightMm" :level="reading?.levelMm.value??null" :good="valid&&reading?.levelMm.quality==='Good'" :color="alarmColor" :ats-points="graphicPoints"/><p class="detail-alarm" :style="{color:alarmColor}">{{alarmText}}</p><p class="help">罐图比例表示液位高度比例。</p><p v-if="tank.temperatureMode==='Ats'" class="help ats-marker-legend">圆点数字为ATS点号，按配置高度定位；未填高度或超出罐高的点仅在下方列表显示。所有正常读取点均参与平均。</p><p v-if="reading?.surfaceBasis" class="notice">{{reading.surfaceBasis}}<br>浮子实际位置P：{{value(reading.floatPositionMm,'level')}} {{unit('level',config.display)}}</p><div class="detail-identity"><p>产品编号 <strong>{{tank.productNumber||'—'}}</strong></p><p>设备批次 <strong>{{tank.batch||'—'}}</strong></p><p>罐径 mm <strong>{{tank.diameterMm??'—'}}</strong></p><p>公称容量 m³ <strong>{{tank.nominalCapacityM3??'—'}}</strong></p><p>所属罐组 <strong>{{config.groups.filter(g=>g.tankIds.includes(tank.id)).map(g=>g.name).join('、')||'—'}}</strong></p><p>仪表位号 <strong>{{tank.instrumentTag||'—'}}</strong></p><p>采集通道 <strong>{{config.channels.find(c=>c.id===tank.channelId)?.name||'—'}}</strong></p><p>仪表地址 / 内部编号 <strong>{{tank.address}}</strong></p><p>仪表状态码 <strong>{{valid?reading?.instrumentStatus??'—':'—'}}</strong></p><p>仪表故障码 <strong>{{valid&&reading?.instrumentFault!==null&&reading?.instrumentFault!==undefined?'0x'+reading.instrumentFault.toString(16).toUpperCase().padStart(4,'0'):'—'}}</strong></p></div><InstrumentControls :reading="reading" :reading-valid="valid" :licensed="licensed" :key="tank.id" :config="config" :tank="tank" :can-operate="canOperate" :dirty="dirty"/><p v-if="tank.notes" class="help archive-notes">备注：{{tank.notes}}</p></article><section class="detail-values"><div class="detail-metrics"><article class="panel detail-metric prominent"><small>液位 {{unit('level',config.display)}}</small><strong>{{value(reading?.levelMm,'level')}}</strong><span>{{quality(reading?.levelMm)}}</span></article><article class="panel detail-metric"><small>温度 ℃ · IR26</small><strong>{{value(reading?.instantTemperatureC,'temperature')}}</strong><span>{{quality(reading?.instantTemperatureC)}}</span></article><article v-if="tank.temperatureMode==='Ats'||averageAllowed&&tank.temperatureMode==='Wireless'" class="panel detail-metric"><small>{{tank.temperatureMode==='Ats'?'温度计实时平均温度 ℃':'最近一次任务平均温度 ℃'}}</small><strong>{{tank.temperatureMode==='Wireless'&&reading?.averageTaskId?displayMetric(reading.averageTemperatureC,'temperature',config.display):value(reading?.averageTemperatureC,'temperature')}}</strong><span>{{tank.temperatureMode==='Ats'?'正常点 '+normalPoints+' / '+tank.atsPointCount:'上次成功完成 '+date(reading?.averageCompletedAtUtc)+(reading?.averageTaskId?' · 任务 '+reading.averageTaskId.slice(0,8):'')}}</span></article><article class="panel detail-metric"><small>仪表实测密度 {{unit('density',config.display)}}</small><strong>{{value(reading?.instrumentDensityKgM3,'density')}}</strong><span>{{quality(reading?.instrumentDensityKgM3)}}</span></article><article class="panel detail-metric prominent"><small>当前净体积 {{unit('volume',config.display)}}</small><strong>{{value(reading?.netVolumeM3,'volume')}}</strong><span>{{quality(reading?.netVolumeM3)}}</span></article><article class="panel detail-metric prominent"><small>产品质量 {{unit('mass',config.display)}}</small><strong>{{value(reading?.massT,'mass')}}</strong><span>{{quality(reading?.massT)}}</span></article><article class="panel detail-metric"><small>修正后当前体积 {{unit('volume',config.display)}}</small><strong>{{value(reading?.currentVolumeM3,'volume')}}</strong><span>扣水前体积</span></article><article class="panel detail-metric"><small>人工水体积 m³</small><strong>{{tank.metering.waterVolumeM3.toLocaleString('zh-CN',{maximumFractionDigits:3})}}</strong><span>用于净体积计算</span></article><article class="panel detail-metric"><small>20℃标准密度 kg/m³</small><strong>{{tank.metering.standardDensity20KgM3??'—'}}</strong><span>人工录入，独立于实测密度</span></article><article v-for="i in [1,2]" :key="i" class="panel detail-metric"><small>压力输入{{i}} {{tank[i===1?'pressure1':'pressure2'].unit==='KPa'?'kPa':tank[i===1?'pressure1':'pressure2'].unit==='MPa'?'MPa':'bar'}}</small><strong>{{tank[i===1?'pressure1':'pressure2'].enabled?pressure(i):'无压力'}}</strong><span>{{tank[i===1?'pressure1':'pressure2'].enabled?quality(reading?.[i===1?'pressure1KPa':'pressure2KPa']):'未配置压力输入'}}</span></article></div><div class="panel detail-source"><p>最近接收：{{date(reading?.receivedAtUtc)}}<br>来源时间：{{reading?.sourceTimeConfirmed?date(reading.sourceAtUtc):'未确认，采用软件接收时间'}}</p><section v-if="valid&&reading?.instrumentFaults.length"><h3>当前仪表故障</h3><p class="help">按软件首次检测时间、同一时间按协议故障编码排序。不是仪表实际发生时间。</p><table><thead><tr><th>故障编码</th><th>含义</th><th>软件首次检测</th></tr></thead><tbody><tr v-for="fault in reading.instrumentFaults" :key="fault.code"><td>{{fault.code}}</td><td>{{fault.description}}</td><td>{{date(fault.firstDetectedAtUtc)}}</td></tr></tbody></table><p v-if="!reading.faultTrackingPersisted" class="error-message">首次检测时间暂未保存，当前显示本次检测值。</p></section><p v-if="reading?.diagnostic" class="error-message">{{reading.diagnostic}}</p><p v-for="note in reading?.calculationNotes" :key="note" class="help">{{note}}</p></div></section><article class="panel detail-ats"><h2>{{tank.temperatureMode==='Ats'?'温度计':tank.temperatureMode==='Wireless'&&averageAllowed?'无线浮子测温':'温度配置'}}</h2><template v-if="tank.temperatureMode==='Ats'"><p class="help">点号从下至上；所有正常点参与算术平均。</p><table><thead><tr><th>点号</th><th>高度 mm</th><th>温度 ℃</th><th>状态</th></tr></thead><tbody><tr v-for="point in points" :key="point.index"><td>{{point.index}}</td><td>{{tank.atsHeightsMm[point.index-1]??'—'}}</td><td>{{value(point.temperatureC,'temperature')}}</td><td :title="point.temperatureC.reason">{{valid?qualityNames[point.temperatureC.quality]:'无效'}}</td></tr><tr v-if="!points.length"><td colspan="4" class="empty">等待采集配置的{{tank.atsPointCount}}点</td></tr></tbody></table></template><p v-else class="help">{{tank.temperatureMode==='None'?'本罐未配置温度计，温度显示为“—”。':averageAllowed?'温度和最近一次任务平均温度分别显示。':'温度取仪表温度。'}}</p></article></section><WirelessTasks :licensed="licensed" v-if="averageAllowed&&tank.temperatureMode==='Wireless'" :key="'wireless-'+tank.id" :config="config" :can-operate="canOperate" :dirty="dirty" :focus-tank="tank.id"/><section class="detail-trend"><div class="toolbar"><h2>单罐实时趋势</h2><button class="button" @click="showTrend=!showTrend">{{showTrend?'收起实时趋势':'展开实时趋势'}}</button></div><TrendBoard :licensed="licensed" v-if="showTrend" :key="tank.id" :config="config" :admin="admin" :dirty="dirty" :focus-tank="tank.id" @updated="emit('updated',$event)"/></section></template>
